window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1a1b4c1027f76718"]={"versions": [{"id": "FIG-1a1b4c1027f76718", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsparametersatzes (BSW Parameter Definition) für den AUTOSAR Classic Platform CAN Driver (<code>Can</code>). Dargestellt ist das Konfigurationsmodell zur signalbasierten Evaluierung von Empfangsnachrichten im Rahmen des Pretended Networking bzw. der autonomen Kommunikationsüberwachung (Pretended Networking / Inter-MCU Communication, <code>CanIcom</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Konfigurationscontainer ist <code>CanIcomRxMessageSignalConfig</code> (Metaklasse <code>EcucParamConfContainerDef</code>, Multiplizität 0..*). Dieser aggregiert über Kompositionen (<code>+parameter</code>):</p>\n<ul class=\"fig-list\"><li><code>CanIcomSignalMask</code> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Bitmaske zur Filterung der Signalbits.\n</li><li><code>CanIcomSignalValue</code> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Erwarteter Signal- oder Referenzwert für die Bedingungsprüfung.\n</li><li><code>CanIcomSignalOperation</code> (<code>EcucEnumerationParamDef</code>): Mathematisch-logische Operation für die Signalprüfung. Aggregiert über Kompositionen (<code>+literal</code>) die Ausprägungen <code>AND</code>, <code>XOR</code>, <code>SMALLER</code>, <code>EQUAL</code> und <code>GREATER</code> (jeweils <code>EcucEnumerationLiteralDef</code>).\n</li></ul>\n<p class=\"fig-p\">Zusätzlich aggregiert der Container über eine Komposition (<code>+reference</code>):</p>\n<ul class=\"fig-list\"><li><code>CanIcomSignalRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1): Verweist über eine gerichtete Assoziation (<code>+destination</code>) auf den externen Zielcontainer <code>ComSignal</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*, Herkunft <code>(from Com)</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Ablauf- oder Sequenzinteraktionen. Zur Laufzeit wendet die CAN-Hardware bzw. der Low-Level-Treiber während des Low-Power-Betriebs (Icom / Pretended Networking) die definierte Maske (<code>CanIcomSignalMask</code>) und die logische Operation (<code>CanIcomSignalOperation</code>) bezogen auf <code>CanIcomSignalValue</code> auf das über <code>CanIcomSignalRef</code> zugeordnete Signal an, um ein Wake-up-Ereignis zu triggern.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche BSW-ECUC-Parameterstruktur für Implementierer des AUTOSAR CAN Drivers sowie für ECUC-Codegeneratoren und Konfigurationswerkzeuge. Fehlt <code>CanIcomSignalRef</code> (Kardinalität 0..1), ist die Signalauswertung generisch auf Bit-/Nachrichtenebene ohne direkte Verknüpfung zu einem <code>ComSignal</code> konfiguriert. Alle Literalwerte und Grenzwerte (<code>min = 0</code>) sind zwingend im Konfigurationsschema abzubilden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2b5092064c1deb12", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsparametersatzes (BSW Parameter Definition) für den AUTOSAR Classic Platform CAN Driver (<code>Can</code>). Dargestellt ist das Konfigurationsmodell zur signalbasierten Evaluierung von Empfangsnachrichten im Rahmen des Pretended Networking bzw. der autonomen Kommunikationsüberwachung (Pretended Networking / Inter-MCU Communication, <code>CanIcom</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Konfigurationscontainer ist <code>CanIcomRxMessageSignalConfig</code> (Metaklasse <code>EcucParamConfContainerDef</code>, Multiplizität 0..*). Dieser aggregiert über Kompositionen (<code>+parameter</code>):</p>\n<ul class=\"fig-list\"><li><code>CanIcomSignalMask</code> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Bitmaske zur Filterung der Signalbits.\n</li><li><code>CanIcomSignalValue</code> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Erwarteter Signal- oder Referenzwert für die Bedingungsprüfung.\n</li><li><code>CanIcomSignalOperation</code> (<code>EcucEnumerationParamDef</code>): Mathematisch-logische Operation für die Signalprüfung. Aggregiert über Kompositionen (<code>+literal</code>) die Ausprägungen <code>AND</code>, <code>XOR</code>, <code>SMALLER</code>, <code>EQUAL</code> und <code>GREATER</code> (jeweils <code>EcucEnumerationLiteralDef</code>).\n</li></ul>\n<p class=\"fig-p\">Zusätzlich aggregiert der Container über eine Komposition (<code>+reference</code>):</p>\n<ul class=\"fig-list\"><li><code>CanIcomSignalRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1): Verweist über eine gerichtete Assoziation (<code>+destination</code>) auf den externen Zielcontainer <code>ComSignal</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Ablauf- oder Sequenzinteraktionen. Zur Laufzeit wendet die CAN-Hardware bzw. der Low-Level-Treiber während des Low-Power-Betriebs (Icom / Pretended Networking) die definierte Maske (<code>CanIcomSignalMask</code>) und die logische Operation (<code>CanIcomSignalOperation</code>) bezogen auf <code>CanIcomSignalValue</code> auf das über <code>CanIcomSignalRef</code> zugeordnete Signal an, um ein Wake-up-Ereignis zu triggern.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche BSW-ECUC-Parameterstruktur für Implementierer des AUTOSAR CAN Drivers sowie für ECUC-Codegeneratoren und Konfigurationswerkzeuge. Fehlt <code>CanIcomSignalRef</code> (Kardinalität 0..1), ist die Signalauswertung generisch auf Bit-/Nachrichtenebene ohne direkte Verknüpfung zu einem <code>ComSignal</code> konfiguriert. Alle Literalwerte und Grenzwerte (<code>min = 0</code>) sind zwingend im Konfigurationsschema abzubilden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-1a1b4c1027f76718", "to": "FIG-2b5092064c1deb12", "fr": "R4.2.2", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Unterstreichung der Klassennamen/Metaklassenbezeichner: In allen Boxen (<code>CanIcomRxMessageSignalConfig</code>, <code>CanIcomSignalMask</code>, <code>CanIcomSignalValue</code>, <code>CanIcomSignalOperation</code>, <code>AND</code>, <code>XOR</code>, <code>SMALLER</code>, <code>GREATER</code>, <code>EQUAL</code>, <code>CanIcomSignalRef</code>, <code>ComSignal</code>) wurde der Doppelpunkt vor der Metaklasse (<code>EcucParamConfContainerDef</code>, <code>EcucIntegerParamDef</code>, etc.) in die Unterstreichung einbezogen und der Leerraum vor dem Doppelpunkt entfernt.\n</li><li>Package-Hinweis: Die Textannotation <code>(from Com)</code> unter dem Container <code>ComSignal</code> wurde entfernt.\n</li><li>Bildbeschnitt: Der untere Bildrand wurde leicht gekürzt.\n</li></ul>"}]};
